package local.blackmamba.vpn;
import android.app.*;import android.text.InputType;import android.view.View;import android.widget.*;import org.json.*;
/** One compact sheet; edits remain a draft until Save. */
final class DnsScreen {
 final MainActivity a;final JSONObject draft;LinearLayout body,manual;TextView result;AlertDialog dialog;boolean expanded,busy;
 DnsScreen(MainActivity a)throws Exception{this.a=a;draft=a.store.snapshot();}
 void show(){body=a.vertical();body.setPaddingRelative(a.dp(20),0,a.dp(20),a.dp(4));ScrollView scroll=new ScrollView(a);scroll.setFillViewport(false);scroll.addView(body);draw();dialog=a.new DialogBuilder(a).setTitle("DNS").setView(scroll).setNegativeButton(L10n.s(R.string.msg_0ec753be8d),null).setPositiveButton(L10n.s(R.string.msg_4864057d62),null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->{try{DnsSettings.validate(draft);if(busy)return;if(a.store.changeDns(draft))TunnelService.reload();dialog.dismiss();a.render();}catch(Exception e){result.setText(e.getMessage());result.setVisibility(View.VISIBLE);}}));a.sheet(dialog);}
 void put(String key,String value){if(busy)return;try{draft.put(key,value);draw();}catch(Exception e){a.message(TunnelService.safeError(e));}}
 void draw(){body.removeAllViews();LinearLayout modes=a.row();
  Button auto=DnsSettings.manual(draft)?a.button(L10n.s(R.string.dns_auto),()->put("dnsMode","auto")):a.primary(L10n.s(R.string.dns_auto),()->{});
  Button own=DnsSettings.manual(draft)?a.primary(L10n.s(R.string.dns_manual),()->{}):a.button(L10n.s(R.string.dns_manual),()->put("dnsMode","manual"));
  modes.addView(auto,new LinearLayout.LayoutParams(0,a.dp(44),1));LinearLayout.LayoutParams second=new LinearLayout.LayoutParams(0,a.dp(44),1);second.setMarginStart(a.dp(8));modes.addView(own,second);body.addView(modes);
  if(DnsSettings.manual(draft)){row(R.string.dns_primary,"remoteDns",false);expandRow();if(expanded){row(R.string.dns_backup,"dnsBackup",true);row(R.string.dns_direct,"dnsDirect",true);row(R.string.dns_bootstrap,"dnsBootstrap",true);}}
  else {try{String net=a.currentNetwork();String selected=draft.optString(draft.optBoolean("auto",true)?net:draft.optString("manual","wifi"));JSONObject node=Store.find(draft.getJSONArray("servers"),selected);String[] dns=DnsSettings.remote(draft,node);LinearLayout source=a.vertical();source.setPaddingRelative(0,a.dp(8),0,a.dp(6));source.addView(a.bold(L10n.s(DnsSettings.providerFor(node).length()>0?R.string.dns_subscription:R.string.dns_builtin),14));source.addView(a.text(name(dns[0])+(dns[1].isEmpty()?"":" · "+name(dns[1])),12,MainActivity.MUTED));body.addView(source);}catch(Exception ignored){}}
  LinearLayout actions=a.row();Button check=a.button(L10n.s(R.string.dns_check),()->check());check.setEnabled(!busy);auto.setEnabled(!busy);own.setEnabled(!busy);actions.addView(check,new LinearLayout.LayoutParams(0,a.dp(44),1));actions.addView(a.helpButton("DNS",L10n.s(R.string.dns_help)),a.lp(44,44));body.addView(actions);result=a.text(busy?L10n.s(R.string.dns_checking):"",12,MainActivity.MUTED);result.setVisibility(busy?View.VISIBLE:View.GONE);body.addView(result);
 }
 void expandRow(){LinearLayout row=a.row();row.setMinimumHeight(a.dp(44));row.addView(a.bold(L10n.s(R.string.msg_d7907f4d43),14),new LinearLayout.LayoutParams(0,-2,1));Icons arrow=new Icons(a,"chevron",MainActivity.MUTED);arrow.setRotation(expanded?90:0);row.addView(arrow,a.lp(16,16));row.setBackground(a.selectable());row.setOnClickListener(v->{if(!busy){expanded=!expanded;draw();}});body.addView(row);a.divider(body);}
 String name(String value){if(value.isEmpty())return L10n.s(R.string.dns_auto);DnsProviders.Provider p=DnsProviders.find(value);if(p==null)return value;return p.name+(p.detail==R.string.dns_threats?" · "+L10n.s(R.string.dns_filter_threats):p.detail==R.string.dns_ads?" · "+L10n.s(R.string.dns_filter_ads):"");}
 void row(int title,String key,boolean optional){String value=draft.optString(key);a.item(body,L10n.s(title),key.equals("dnsBackup")&&value.isEmpty()?L10n.s(R.string.dns_none):name(value),()->pick(title,key,optional));}
 void pick(int title,String key,boolean optional){if(busy)return;
  LinearLayout choices=a.vertical();choices.setPaddingRelative(a.dp(16),0,a.dp(16),0);ScrollView scroll=new ScrollView(a);scroll.setVerticalScrollBarEnabled(false);scroll.addView(choices);
  AlertDialog picker=a.new DialogBuilder(a).setTitle(L10n.s(title)).setView(scroll).setNegativeButton(L10n.s(R.string.msg_0ec753be8d),null).create();
  if(optional)a.item(choices,L10n.s(key.equals("dnsBackup")?R.string.dns_none:R.string.dns_auto),key.equals("dnsBackup")?null:L10n.s(R.string.dns_android),()->{picker.dismiss();put(key,"");});
  for(DnsProviders.Provider p:DnsProviders.ALL)a.item(choices,p.name,L10n.s(p.detail),()->{picker.dismiss();put(key,p.address);});
  a.item(choices,L10n.s(R.string.dns_custom),"DoH · DoT · UDP · TCP",()->{picker.dismiss();custom(title,key);});a.sheet(picker);
 }
 void custom(int title,String key){LinearLayout box=a.vertical();box.setPaddingRelative(a.dp(20),a.dp(8),a.dp(20),0);EditText field=a.edit("https://…/dns-query",draft.optString(key));field.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);field.setTextDirection(View.TEXT_DIRECTION_LTR);box.addView(field);a.note(box,"DoH · DoT · UDP · TCP");AlertDialog edit=a.new DialogBuilder(a).setTitle(L10n.s(title)).setView(box).setNegativeButton(L10n.s(R.string.msg_0ec753be8d),null).setPositiveButton(L10n.s(R.string.msg_4864057d62),null).create();edit.setOnShowListener(v->edit.getButton(-1).setOnClickListener(w->{try{String value=DnsSettings.address(field.getText().toString());edit.dismiss();put(key,value);}catch(Exception e){field.setError(e.getMessage());}}));a.sheet(edit);}
 void check(){if(busy)return;try{DnsSettings.validate(draft);JSONObject snapshot=new JSONObject(draft.toString());busy=true;draw();dialog.getButton(-1).setEnabled(false);new Thread(()->{String text;try{text=DnsChecker.check(a.getApplicationContext(),snapshot);}catch(Exception e){text=L10n.s(R.string.dns_check_failed);}String value=text;a.runOnUiThread(()->{busy=false;if(dialog!=null&&dialog.isShowing()){draw();dialog.getButton(-1).setEnabled(true);result.setText(value);result.setVisibility(View.VISIBLE);}});},"dns-check").start();}catch(Exception e){result.setText(e.getMessage());result.setVisibility(View.VISIBLE);}}
}
